import re

def calc(expr):
    tokens = re.findall(r'\d+|[+\-*/()]', expr)
    pos = 0

    def peek():
        nonlocal pos
        if pos < len(tokens):
            return tokens[pos]
        return None

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        val = parse_term()
        while peek() in ('+', '-'):
            op = advance()
            rhs = parse_term()
            if op == '+':
                val = val + rhs
            else:
                val = val - rhs
        return val

    def parse_term():
        val = parse_factor()
        while peek() in ('*', '/'):
            op = advance()
            rhs = parse_factor()
            if op == '*':
                val = val * rhs
            else:
                val = int_div(val, rhs)
        return val

    def parse_factor():
        if peek() == '-':
            advance()
            return -parse_factor()
        return parse_primary()

    def parse_primary():
        tok = peek()
        if tok == '(':
            advance()
            val = parse_expr()
            # expect ')'
            if peek() == ')':
                advance()
            return val
        else:
            advance()
            return int(tok)

    def int_div(a, b):
        sign = 1 if (a < 0) == (b < 0) else -1
        return sign * (abs(a) // abs(b))

    result = parse_expr()
    return result

